/* SheetJS CE 0.20.3 is loaded locally only when Excel transfer is requested. */
(function(root){
 const profileColumns=['Technician ID','Full Name','Mobile Number','Role / Specialization','CPR Number','CPR Expiry Date','Visa Number','Visa Expiry Date'];
 const passColumns=['Technician ID','Pass ID','Gate Pass Name','Gate Pass Location','Gate Pass Number','Gate Pass Expiry Date'];
 const teamColumns=['Team ID','Team Name','Technician ID'];
 const key=id=>String(id??'').trim().replace(/^0+(?=\d)/,'');
 const date=value=>{if(value===null||value===undefined||value==='')return '';if(value instanceof Date)return value.getFullYear()+'-'+String(value.getMonth()+1).padStart(2,'0')+'-'+String(value.getDate()).padStart(2,'0');if(typeof value==='number'){const p=root.XLSX.SSF.parse_date_code(value);return p?p.y+'-'+String(p.m).padStart(2,'0')+'-'+String(p.d).padStart(2,'0'):String(value);}const text=String(value).trim();if(/^\d{4}-\d{2}-\d{2}$/.test(text))return text;const m=text.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})$/);return m?m[3]+'-'+m[2].padStart(2,'0')+'-'+m[1].padStart(2,'0'):text;};
 function buildWorkbook(data){
  const X=root.XLSX,book=X.utils.book_new(),backup=[];
  const saveRaw=(entity,id,value)=>{const text=JSON.stringify(value);for(let at=0,part=1;at<text.length;at+=30000,part++)backup.push([entity,String(id),part,text.slice(at,at+30000)]);};
  const add=(name,headers,rows,widths)=>{const ws=X.utils.aoa_to_sheet([headers,...rows],{dateNF:'yyyy-mm-dd'});ws['!cols']=widths.map(wch=>({wch}));ws['!autofilter']={ref:X.utils.encode_range({s:{r:0,c:0},e:{r:Math.max(rows.length,1),c:headers.length-1}})};X.utils.book_append_sheet(book,ws,name);};
  const passes=[];const excelDate=value=>{const m=String(value||'').match(/^(\d{4})-(\d{2})-(\d{2})$/);return m?new Date(Number(m[1]),Number(m[2])-1,Number(m[3])):value||'';};
  const technicians=(data.technicians||[]).map(t=>{saveRaw('technician',t.id,t);const items=Array.isArray(t.passes)?t.passes:t.availablePass?[{id:'existing-pass',name:t.availablePass,location:t.passLocation||'',number:t.passNumber||'',expiryDate:t.passExpiryDate||''}]:[];items.forEach((p,i)=>passes.push([String(t.id),p.id||'',p.name||'',p.location||'',p.number||'',excelDate(p.expiryDate)]));return [String(t.id),t.name||'',String(t.mobileNumber||''),t.role||'',String(t.cprNumber||''),excelDate(t.cprExpiryDate),String(t.visaNumber||''),excelDate(t.visaExpiryDate)];});
  add('Technicians',profileColumns,technicians,[18,28,20,28,22,20,22,20]);add('Gate Passes',passColumns,passes,[18,24,28,28,24,23]);
  for(const [name,type,teams] of [['Saturday Teams','saturday',data.saturdayTeams||[]],['Callout Teams','callout',data.calloutTeams||[]]]){const rows=[];for(const t of teams){saveRaw(type,t.id,t);for(const id of t.technicianIds||[])rows.push([t.id,t.name||'',String(id)]);}add(name,teamColumns,rows,[22,28,18]);}
  add('Backup Data',['Entity','ID','Part','Data'],backup,[18,22,10,60]);
  add('Instructions',['Field','How to fill'],[['Technicians','Enter one technician per row. Technician ID and Full Name are required.'],['Technician ID','Use 1–5 digits. Keep IDs as text to preserve leading zeros. Existing IDs are skipped.'],['Mobile Number','Optional, exactly 8 digits. Keep mobile and document numbers as text.'],['Dates','Use YYYY-MM-DD or an Excel date cell. Day/month/year dates are also accepted.'],['Gate Passes','Optional. Enter one pass per row and match its Technician ID. Name and expiry date are required.'],['Pass ID','Optional for new passes; keep existing IDs on exported files.'],['Teams','Optional. Add one row per technician membership. Keep team IDs consistent.'],['Backup Data','Keep this sheet unchanged on exports. It preserves additional profile, pass and team data.'],['Import','Save as .xlsx, import on the website, review the preview, then confirm.']],[24,110]);
  return book;
 }
 function parseWorkbook(book){
  const X=root.XLSX;if(!book.Sheets.Technicians)throw Error('The workbook needs a Technicians sheet. Download the import template.');
  for(const name of book.SheetNames){const ws=book.Sheets[name];if(ws['!ref']){const range=X.utils.decode_range(ws['!ref']);if(range.e.r>20000||range.e.c>100)throw Error('Workbook is too large. Limit technician files to 1,000 profiles.');}}
  const rows=name=>book.Sheets[name]?X.utils.sheet_to_json(book.Sheets[name],{defval:'',raw:true}).filter(r=>Object.values(r).some(v=>v!=='')):[];
  const raw=new Map(),chunks=new Map();
  for(const r of rows('Backup Data')){if(!['technician','saturday','callout'].includes(r.Entity))continue;const id=r.Entity+':'+String(r.ID),list=chunks.get(id)||[];list.push([Number(r.Part),String(r.Data)]);chunks.set(id,list);}
  for(const [id,list] of chunks){const text=list.sort((a,b)=>a[0]-b[0]).map(x=>x[1]).join('');if(text.length>200000)throw Error('A backup record is too large.');try{raw.set(id,JSON.parse(text));}catch{throw Error('Backup Data is damaged. Use the original export or remove the Backup Data sheet.');}}
  const source=rows('Technicians');if(source.length>1000)throw Error('Import up to 1,000 technicians at a time.');
  const technicians=source.map(r=>{const id=String(r['Technician ID']??'').trim(),base=raw.get('technician:'+id)||{};return {...base,id,name:String(r['Full Name']??'').trim(),mobileNumber:String(r['Mobile Number']??'').trim(),role:String(r['Role / Specialization']??''),cprNumber:String(r['CPR Number']??''),cprExpiryDate:date(r['CPR Expiry Date']),visaNumber:String(r['Visa Number']??''),visaExpiryDate:date(r['Visa Expiry Date']),passes:[]};});
  const passRows=rows('Gate Passes');for(const [index,r] of passRows.entries()){const id=key(r['Technician ID']),tech=technicians.find(t=>key(t.id)===id);if(!tech)throw Error('Gate Passes row '+(index+2)+' refers to a technician missing from the Technicians sheet.');const passId=String(r['Pass ID']||'gate-pass-'+tech.id+'-'+index),base=raw.get('technician:'+tech.id)?.passes?.find(p=>p.id===passId)||{};tech.passes.push({...base,id:passId,name:String(r['Gate Pass Name']||''),location:String(r['Gate Pass Location']||''),number:String(r['Gate Pass Number']||''),expiryDate:date(r['Gate Pass Expiry Date'])});}
  const teams=(name,type)=>{const result=new Map();for(const r of rows(name)){const id=String(r['Team ID']||'').trim(),member=String(r['Technician ID']||'').trim();if(!id||!member)throw Error(name+' rows need a Team ID and Technician ID.');if(!technicians.some(t=>key(t.id)===key(member)))throw Error(name+' refers to a technician missing from the Technicians sheet.');let t=result.get(id);if(!t){t={...(raw.get(type+':'+id)||{}),id,name:String(r['Team Name']||id),technicianIds:[]};result.set(id,t);}if(!t.technicianIds.includes(member))t.technicianIds.push(member);}for(const [id,value] of raw)if(id.startsWith(type+':')&&!result.has(value.id))result.set(value.id,{...value,technicianIds:[]});return [...result.values()];};
  return {technicians,saturdayTeams:teams('Saturday Teams','saturday'),calloutTeams:teams('Callout Teams','callout')};
 }
 root.TMTechnicianExcel={buildWorkbook,parseWorkbook,profileColumns,passColumns,teamColumns};
})(typeof window==='undefined'?globalThis:window);
